# -*- coding: utf-8 -*-
S = "полный обзор задач 11 класса (очередь G9–G11), условие сверено с текстом учебника (§20, №7), ключ проверен вычислением"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G11_TB_§20_7_2", r"в условии OCR исказил «$2\log_{27}3$» в «$2\log_{2}73$» (в ключе и в учебнике: $\log_{27}3$). Проверка: $8^{\frac13\log_{2}\frac{31}{32}\cdot2\cdot\frac13}=2^{\frac23\log_{2}\frac{31}{32}}=\left(\frac{31}{32}\right)^{2/3}<1<\sqrt{15}$",
  q=r"Сравните значения данных числовых выражений: $\sqrt{15}$ и $8^{\frac{1}{3}\log_{2}\left(1-\frac{1}{32}\right) \cdot 2\log_{27} 3}$",
  dnew={0: (r"$\sqrt{15} < 8^{\frac{1}{3} \log_{2} \left(1 - \frac{1}{32}\right) \cdot 2 \log_{27} 3}$", r"Ученик принял $\log_{2}\left(1-\frac{1}{32}\right)$ за $\log_{2}32=5$ и получил показатель $\frac13\cdot5\cdot\frac23=\frac{10}{9}$, то есть $8^{10/9}=2^{10/3}\approx10{,}1>\sqrt{15}$; но $\log_{2}\frac{31}{32}<0$, и степень меньше $1$."),
        1: (r"$\sqrt{15} = 8^{\frac{1}{3} \log_{2} \left(1 - \frac{1}{32}\right) \cdot 2 \log_{27} 3}$", r"Ученик решил, что оба выражения — корни из целых чисел и совпадают, не вычисляя степень; на деле $8^{\dots}=\left(\frac{31}{32}\right)^{2/3}<1$, а $\sqrt{15}\approx3{,}87$.")})
E("G11_TB_§24_1", r"условие было текстом доказательства (без вопроса); сформулирован вопрос, ключ дополнен обоснованием $(F+C)'=F'+0=f$",
  q=r"Функция $F(x)$ является первообразной для функции $f(x)$ на промежутке $I$, $C$ — произвольная постоянная. Что можно сказать о функции $F(x)+C$? Ответ обоснуйте.",
  k=r"Если $F(x)$ — первообразная для $f(x)$ на промежутке $I$, то $F(x)+C$, где $C$ — произвольная постоянная, также является первообразной для $f(x)$ на $I$, так как $(F(x)+C)'=F'(x)+C'=f(x)+0=f(x)$.")
